local pattern = "[%z\1-\127\194-\244][\128-\191]*"
function U.Characters(text)
 local result = {}
 for char in text:gmatch(pattern) do result[#result + 1] = char end
 return result
end
function U.Length(text)
 local _, count = text:gsub("[^\128-\191]", "")
 return count
end
function U.NFC(text)
 return (text:gsub("[A-Za-z\194-\244][\128-\191]*[\204\205][\128-\191]+", function(s) return compose[s] or s end))
end
function U.Lower(text)
 text = U.NFC(text):gsub("’", "'")
 return (text:gsub(pattern, function(c) return lower[c] or c end):gsub("ĳ", "ij"))
end
function U.Upper(text)
 return (U.NFC(text):gsub(pattern, function(c) return upper[c] or c end))
end
function U.IsWord(text)
 local letters = false
 for c in text:gmatch(pattern) do
  if latin[c] then letters = true elseif c ~= "'" then return false end
 end
 return letters
end
function U.IsLetter(char) return latin[char] == true end
function U.IsMark(char) return char:match("^[\204\205][\128-\191]$") ~= nil end
function U.IsUpper(text)
 return U.Upper(text) == text and U.Lower(text) ~= text
end
function U.InitialUpper(text)
 local first = text:match("^" .. pattern)
 return first and U.Upper(first) == first and U.Lower(first) ~= first
end
function U.Title(text)
 local first = text:match("^" .. pattern)
 return first and U.Upper(first) .. text:sub(#first + 1) or text
end
